`,c.jsx(u.p,{children:"The first month of my capstone project is coming to an end, and I can now move on to working on the Echelon AI Class Card now that a branch has been set up for us to develop in. I’m excited to see what the rest of this journey brings and what I’ll learn along the way!"})]})}function U1(o={}){const{wrapper:u}=o.components||{};return u?c.jsx(u,{...o,children:c.jsx(Ah,{...o})}):Ah(o)}const fm=Object.freeze(Object.defineProperty({__proto__:null,default:U1,frontmatter:N1},Symbol.toStringTag,{value:"Module"})),k1={title:"Working on the Echelon Class Card UI",date:"9/7/2025",wordCount:357};function Ch(o){const u={em:"em",img:"img",li:"li",p:"p",ul:"ul",...o.components};return c.jsxs(c.Fragment,{children:[c.jsx(u.p,{children:"This week marks the beginning of the second month of my capstone project! Now that the coding environment is set up for us and we’ve learned the foundations of Compose and Kotlin, we can get to actually work on the Echelon app. As I mentioned in previous blog posts, I assigned myself a ticket from the Jira board to work on the UI of the class cards. This week I started creating the composable functions that make up this card."}),`
